      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is an extraordinarily powerful relation connecting gravity and quantum field theory and has reshaped work across theoretical physics.",
        "attribution": "Maldacena introduced the correspondence, and Witten clarified and extended its implications; their contributions are central to its establishment.",
        "maturity": "The duality has survived extensive theoretical scrutiny and generated useful results, but direct empirical confirmation of the gravitational correspondence remains absent.",
        "uncertainties": [
          "Whether a theoretical framework without decisive observational confirmation meets the discovery standard.",
          "How to distinguish the correspondence itself from later applications and developments."
        ]
      }
    },
